'use strict';

const { info, warn, bold, dim, error } = require('../../../../lib/util/term');
const { UPGRADE_DIR, REPORT_FILE } = require('../../constants');

const { setup } = require('./setup');
const Detector = require('./detector');
const Evaluator = require('./evaluator');
const { evaluateCompilerRules, classifyFindings } = require('./classification');

async function analyze(ctx) {
  console.log();
  console.log(bold('Code Analysis'));
  console.log();

  ctx.analysis = {
    timestamp: new Date().toISOString(),
    findings: [],
    rulesScanned: 0,
    compilerRan: false,
    error: null,
  };
  const setupResult = setup();
  if (setupResult.error) {
    ctx.analysis.error = setupResult.error;
    console.log(`  ${error(setupResult.error)}`);
    return;
  }

  const { rules, languages, projectFiles, fileCache, nonSourceFiles } = setupResult;
  ctx.analysis.rulesScanned = rules.length;
  ctx.analysis.languages = languages;
  ctx.rules = rules;

  const detector = new Detector();
  const {
    compilerMessages, cdsEnvOutput, patternRules, compilerRules
  } = await detector.run(rules);

  ctx.analysis.compilerRan = compilerMessages !== null;

  const evaluator = new Evaluator(projectFiles, nonSourceFiles, fileCache, cdsEnvOutput);
  const patternResults = evaluator.evaluateRules(patternRules);
  const compilerResults = evaluateCompilerRules(compilerRules, compilerMessages || []);

  classifyFindings(ctx, [...patternResults, ...compilerResults]);
  ctx.analysis.warnings = detector.warnings;
  if (detector.warnings.length > 0) {
    const count = detector.warnings.length;
    console.log(`  ${warn(`${count} warning${count > 1 ? 's' : ''} during analysis`)}`);
    if (ctx.shouldReport) {
      console.log(`  ${dim(`see ${UPGRADE_DIR}/${REPORT_FILE} for details`)}`);
    } else {
      for (const w of detector.warnings) {
        const line = w.split('\n')[0].slice(0, 80);
        console.log(`    ${dim(line)}`);
      }
    }
  }
}

const SECTION_ORDER = [
  'Prepare for Migration',
  'Stricter CDS Compiler Checks',
  'Runtime Changes',
  'Non-Breaking Changes',
  'Flags Entirely Removed',
  'Java / Spring Boot Migration',
];

function printSummary(ctx) {
  const findings = ctx.analysis.findings;
  if (findings.length === 0) {
    console.log(`  ${info('No issues found.')}`);
    return;
  }

  const totalMatches = findings.reduce((sum, f) => sum + f.matches.length, 0);
  const bySection = new Map();
  for (const f of findings) {
    const section = f.capireSection || 'Other';
    if (!bySection.has(section)) bySection.set(section, []);
    bySection.get(section).push(f);
  }

  const orderedSections = SECTION_ORDER.filter(s => bySection.has(s));
  for (const s of bySection.keys()) {
    if (!orderedSections.includes(s)) orderedSections.push(s);
  }

  for (const section of orderedSections) {
    const group = bySection.get(section);
    console.log(`  ${bold(section)}`);
    console.log();
    for (const finding of group) {
      const url = finding.capireAnchor || '';
      const titleLine = url ? `    ${finding.title}  ${dim(url)}` : `    ${finding.title}`;
      console.log(titleLine);
      for (const m of finding.matches) {
        if (m.source === 'openrewrite') {
          if (m.file) {
            const loc = m.line != null ? `${m.file}:${m.line}${m.col != null ? ':' + m.col : ''}` : m.file;
            console.log(`      ${loc}  ${dim('(auto-fixable)')}`);
          } else {
            console.log(`      ${dim('(auto-fixable, no specific locations)')}`);
          }
        } else if (m.file === '<cds env>') {
          const context = m.context ? ` – ${m.context.trim()}` : '';
          const note = m.valueStatus === 'default' ? ' – safe to remove' : '';
          console.log(`      ${dim(`cds env (line ${m.line})${context}${note}`)}`);
        } else {
          const loc = m.line ? `${m.file}:${m.line}${m.col ? ':' + m.col : ''}${m.colEnd ? '-' + m.colEnd : ''}` : m.file;
          const note = m.valueStatus === 'default' ? dim(' – safe to remove') : '';
          console.log(`      ${loc}${note}`);
        }
      }
    }
    console.log();
  }

  console.log(`  ${dim(`${totalMatches} match${totalMatches > 1 ? 'es' : ''} total`)}`);
}

module.exports = { analyze, printSummary };
